MockClient buildBtcAnalyzeMockClient() {
  return MockClient((request) async {
    final url = request.url.toString();

    if (url ==
        'https://api.bybit.com/v5/market/instruments-info?category=linear&baseCoin=BTC') {
      return http.Response(_btcInstrumentsResponseJson, 200);
    }

    if (url ==
        'https://api.bybit.com/v5/market/tickers?category=linear&symbol=BTCUSDT') {
      return http.Response(_btcTickerResponseJson, 200);
    }

    if (url ==
        'https://api.bybit.com/v5/market/orderbook?category=linear&symbol=BTCUSDT&limit=50') {
      return http.Response(_btcOrderbookResponseJson, 200);
    }

    if (url ==
        'https://api.coingecko.com/api/v3/coins/markets?vs_currency=usd&symbols=BTC') {
      return http.Response(_btcCoinGeckoResponseJson, 200);
    }

    throw StateError('Unhandled BTC analyze request: $url');
  });
}

